      payload.optical_constraints=[...document.querySelectorAll('.optimizer-optical-constraint')].map(row=>({wavelength_um:Number(row.querySelector('[data-role="wavelength"]').value),observable:row.querySelector('[data-role="observable"]').value.trim()||undefined,quantity:row.querySelector('[data-role="observable"]').value.trim()?'expression':'expression',expression:row.querySelector('[data-role="expression"]').value.trim(),label:row.querySelector('[data-role="label"]').value.trim(),lower:row.querySelector('[data-role="lower"]').value.trim()===''?null:Number(row.querySelector('[data-role="lower"]').value),upper:row.querySelector('[data-role="upper"]').value.trim()===''?null:Number(row.querySelector('[data-role="upper"]').value)}));
